import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem85 preserva operação e identidade sem inventar alimentação ou impermeabilidade',()=>{for(const [id,titulo] of [['iXzsMyqf9ilSKwbLDtk7','Tênis Masculino Esportivo Creation Molas Academia Caminhada'],['J6WCPaTR5KOqjsAC1nM7','Lampada Led Solar Recarregável Camping Usb Pesca Jardim Lampiao Viagem Several'],['j8z58qFPJKTUJogf5HTM','Celular Smartphone Realme Note 80s 128gb 4gb Ram Dual Sim Bateria 6000mah Ultrafino 7,94 Mm Resistência À Poeira E Água Ip54']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/impermeável|bivolt|127\/220|catálogo confirmado|amortecimento comprovado/i);assert.doesNotMatch(x.comentario,/IP68|IP69|entrada de 5 V|\d+ lumens/i);}});
